/* ==UserStyle==
@name           Red Aura Wallpaper
@namespace      red-aura
@version        1.0.0
@description    Dark red neon theme with custom wallpaper
==/UserStyle== */


/* ================================
   RED AURA
   ================================ */

:root {
    --red: #ff2020;
    --red-bright: #ff4b4b;
    --red-dark: #650000;
    --black: #050000;
    --glass: rgba(12, 0, 0, 0.78);
}


/* ================================
   WALLPAPER
   ================================ */

body {
    background-color: #050000 !important;

    background-image:
        linear-gradient(
            rgba(5, 0, 0, 0.62),
            rgba(5, 0, 0, 0.78)
        ),
        url("https://rawcdn.githack.com/mazrouaa-dev/discord-background/main/wallpaper.png?raw=true") !important;

    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-attachment: fixed !important;

    color: #ffeaea !important;
}


/* ================================
   RED ATMOSPHERE
   ================================ */

body::before {
    content: "";

    position: fixed;
    inset: 0;

    pointer-events: none;

    z-index: 999999;

    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(255, 0, 0, 0.18),
            transparent 32%
        ),
        radial-gradient(
            circle at 85% 80%,
            rgba(180, 0, 0, 0.15),
            transparent 35%
        );

    mix-blend-mode: screen;
}


/* ================================
   HEADINGS
   ================================ */

h1,
h2,
h3,
h4,
h5,
h6 {
    color: #ff4141 !important;

    text-shadow:
        0 0 5px rgba(255, 0, 0, .7),
        0 0 18px rgba(255, 0, 0, .35);
}


/* ================================
   LINKS
   ================================ */

a {
    color: #ff5050 !important;

    transition:
        color .2s ease,
        text-shadow .2s ease;
}

a:hover {
    color: #ff9999 !important;

    text-shadow:
        0 0 8px #ff2020,
        0 0 18px rgba(255, 0, 0, .5);
}


/* ================================
   BUTTONS
   ================================ */

button,
input[type="button"],
input[type="submit"],
input[type="reset"] {

    background:
        linear-gradient(
            135deg,
            #ff3030,
            #850000
        ) !important;

    color: white !important;

    border: 1px solid rgba(255, 100, 100, .55) !important;

    border-radius: 9px !important;

    box-shadow:
        0 0 10px rgba(255, 0, 0, .3),
        inset 0 1px rgba(255,255,255,.15) !important;

    transition:
        transform .15s ease,
        filter .15s ease,
        box-shadow .15s ease !important;
}

button:hover,
input[type="button"]:hover,
input[type="submit"]:hover {

    transform: translateY(-1px) !important;

    filter: brightness(1.18) !important;

    box-shadow:
        0 0 15px rgba(255, 0, 0, .65),
        0 0 30px rgba(255, 0, 0, .25) !important;
}


/* ================================
   INPUTS
   ================================ */

input,
textarea,
select {

    background:
        rgba(15, 0, 0, .82) !important;

    color: #fff0f0 !important;

    border:
        1px solid rgba(255, 40, 40, .35) !important;

    border-radius: 8px !important;

    outline: none !important;
}

input:focus,
textarea:focus,
select:focus {

    border-color: #ff3030 !important;

    box-shadow:
        0 0 0 2px rgba(255, 0, 0, .12),
        0 0 15px rgba(255, 0, 0, .3) !important;
}


/* ================================
   GLASS PANELS
   ================================ */

main,
article,
section,
aside,
nav {

    border-color:
        rgba(255, 40, 40, .2) !important;
}


/* ================================
   CARDS
   ================================ */

[class*="card"],
[class*="Card"],
[class*="panel"],
[class*="Panel"] {

    background:
        rgba(12, 0, 0, .68) !important;

    border:
        1px solid rgba(255, 35, 35, .2) !important;

    box-shadow:
        0 8px 30px rgba(0, 0, 0, .35),
        inset 0 1px rgba(255, 60, 60, .05) !important;

    backdrop-filter: blur(8px);
}


/* ================================
   TEXT
   ================================ */

p,
span,
label,
li {

    text-shadow:
        0 0 2px rgba(255, 0, 0, .12);
}


/* ================================
   CODE BLOCKS
   ================================ */

pre,
code {

    background:
        rgba(5, 0, 0, .9) !important;

    color:
        #ff8585 !important;

    border:
        1px solid rgba(255, 30, 30, .25) !important;
}


/* ================================
   SELECTION
   ================================ */

::selection {

    background:
        #e00000 !important;

    color:
        white !important;
}


/* ================================
   SCROLLBAR
   ================================ */

::-webkit-scrollbar {

    width: 10px;
    height: 10px;
}

::-webkit-scrollbar-track {

    background:
        #080000 !important;
}

::-webkit-scrollbar-thumb {

    background:
        linear-gradient(
            180deg,
            #ff3030,
            #680000
        ) !important;

    border-radius: 20px;

    border: 2px solid #080000;
}

::-webkit-scrollbar-thumb:hover {

    background:
        linear-gradient(
            180deg,
            #ff5555,
            #a00000
        ) !important;
}


/* ================================
   HORIZONTAL LINES
   ================================ */

hr {

    border: none !important;

    border-top:
        1px solid rgba(255, 40, 40, .25) !important;
}


/* ================================
   IMAGES
   ================================ */

img {

    border-radius: 6px;
}


/* ================================
   GLOWING RED BORDER
   ================================ */

[role="button"]:hover {

    border-color:
        rgba(255, 40, 40, .5) !important;

    box-shadow:
        0 0 12px rgba(255, 0, 0, .2) !important;
}
